function renderMarkers(d){markers.innerHTML=d.slice(0,240).map(c=>`<button class="marker" style="left:${(c.lon-21.5)/6.9*78+10}%;top:${(59.9-c.lat)/2.5*66+17}%" data-id="${c.id}" aria-label="${esc(c.name)}"></button>`).join('')+(userLocation?`<span class="marker user" style="left:${(userLocation.lon-21.5)/6.9*78+10}%;top:${(59.9-userLocation.lat)/2.5*66+17}%"></span>`:'');document.querySelectorAll('.marker[data-id]').forEach(e=>e.onclick=()=>openCamera(e.dataset.id))}
